def test_get_user_by_username(api_client, api_key, username, expected_status_code, expected_response, is_valid):
    """
    Tests the /user/{username} endpoint by verifying response status and content.
    """
    headers = {"Authorization": f"Bearer {api_key}"} if is_valid else {}
    response = api_client.get(f"/user/{username}", headers=headers)

    assert response.status_code == expected_status_code

    if expected_status_code == 200:
        response_data = response.json()
        assert response_data == expected_response, "Response content does not match the expected data."
    elif expected_status_code in [400, 404]:
        assert response.text == json.dumps(expected_response) if expected_response else response.text
    else:
        assert response.status_code == 500, "Expected server error for unexpected cases."

